def transform(grid):
    from collections import Counter

    # Count all cells to identify background
    cell_counts = Counter()
    for row in grid:
        for val in row:
            cell_counts[val] += 1

    background = cell_counts.most_common(1)[0][0]

    # Find all connected components
    R = len(grid)
    C = len(grid[0])
    visited = [[False] * C for _ in range(R)]
    comp_list = []

    for r in range(R):
        for c in range(C):
            if grid[r][c] != background and not visited[r][c]:
                component = []
                stack = [(r, c)]
                visited[r][c] = True

                while stack:
                    curr_r, curr_c = stack.pop()
                    component.append((curr_r, curr_c))

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] != background and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))

                comp_list.append((len(component), component))

    if not comp_list:
        return grid

    # Get largest component
    _, largest = max(comp_list, key=lambda x: x[0])

    # Calculate bounding box
    coords = set(largest)
    min_r, max_r = min(r for r, c in coords), max(r for r, c in coords)
    min_c, max_c = min(c for r, c in coords), max(c for r, c in coords)

    # Build result within bounding box
    result = []
    for r in range(min_r, max_r + 1):
        result.append([])
        for c in range(min_c, max_c + 1):
            if (r, c) in coords:
                result[-1].append(grid[r][c])
            else:
                result[-1].append(background)

    return result
