def transform(grid):
    from collections import Counter

    # Count frequencies to find background
    bg_freq = Counter()
    for row in grid:
        for x in row:
            bg_freq[x] += 1
    background = bg_freq.most_common(1)[0][0]

    R, C = len(grid), len(grid[0])
    seen = [[False]*C for _ in range(R)]

    def find_comp(r, c):
        cells = [(r, c)]
        seen[r][c] = True
        stack = [(r, c)]
        while stack:
            cur_r, cur_c = stack.pop()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cur_r + dr, cur_c + dc
                if 0 <= nr < R and 0 <= nc < C and not seen[nr][nc] and grid[nr][nc] != background:
                    seen[nr][nc] = True
                    stack.append((nr, nc))
                    cells.append((nr, nc))
        return cells

    comps = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] != background and not seen[r][c]:
                comps.append(find_comp(r, c))

    if not comps:
        return grid

    # Largest component by cell count
    best = max(comps, key=len)

    # Bounding box
    rs, re = min(r for r,c in best), max(r for r,c in best)
    cs, ce = min(c for r,c in best), max(c for r,c in best)

    # Output
    out = []
    for r in range(rs, re + 1):
        line = []
        for c in range(cs, ce + 1):
            if (r,c) in [(r,c) for r,c in best]:
                line.append(grid[r][c])
            else:
                line.append(background)
        out.append(line)

    return out
